"""Data models for transactions and blocks."""
from __future__ import annotations

import json
from dataclasses import dataclass

from . import crypto

# Block lifecycle states for the confirm/rollback state machine.
STATUS_PENDING = "pending"
STATUS_CONFIRMED = "confirmed"
BLOCK_STATUSES = (STATUS_PENDING, STATUS_CONFIRMED)


@dataclass
class Transaction:
    sender: str
    recipient: str
    amount: int
    signature: str
    # None marks a legacy transfer signed over crypto.canonical_message; a
    # non-boolean non-negative integer marks a sequenced transfer signed over
    # crypto.sequenced_message and bound to the sender's per-account sequence.
    nonce: int | None = None

    @property
    def message(self) -> bytes:
        if self.nonce is None:
            return crypto.canonical_message(self.sender, self.recipient, self.amount)
        return crypto.sequenced_message(
            self.sender, self.recipient, self.amount, self.nonce
        )

    @property
    def tx_id(self) -> str:
        return crypto.compute_tx_id(self.message)

    @property
    def sequenced(self) -> bool:
        return self.nonce is not None

    def to_dict(self) -> dict:
        """JSON-safe representation used both for storage and API output."""
        result = {
            "from": self.sender,
            "to": self.recipient,
            "amount": self.amount,
            "signature": self.signature,
        }
        # The nonce is present only on sequenced transfers, so a legacy
        # transaction keeps its exact five-field wire shape.
        if self.nonce is not None:
            result["nonce"] = self.nonce
        result["tx_id"] = self.tx_id
        return result

    @classmethod
    def from_dict(cls, data: dict) -> "Transaction":
        # The raw JSON value is validated BEFORE any use: no int()/str()
        # coercion, so a string, float or boolean amount can never masquerade
        # as the integer it converts to. bool is an int subclass and must be
        # rejected explicitly.
        amount = data["amount"]
        if isinstance(amount, bool) or not isinstance(amount, int):
            raise ValueError("transaction amount must be an integer")
        # A present nonce must already be a non-boolean, non-negative integer
        # — never a coercible string, float, bool or negative. A missing key
        # denotes a legacy transfer and stays None.
        nonce = data.get("nonce")
        if nonce is not None and (
            isinstance(nonce, bool) or not isinstance(nonce, int) or nonce < 0
        ):
            raise ValueError("transaction nonce must be a non-negative integer")
        return cls(
            sender=data["from"],
            recipient=data["to"],
            amount=amount,
            signature=data["signature"],
            nonce=nonce,
        )


def block_header_bytes(height: int, prev_hash: str, merkle: str) -> bytes:
    """Deterministic serialization of the fields covered by the block hash.

    No timestamp is included: a block with the same parent and the same ordered
    transactions must always hash identically.
    """
    header = {"height": height, "merkle_root": merkle, "prev_hash": prev_hash}
    return json.dumps(header, sort_keys=True, separators=(",", ":")).encode("utf-8")


def compute_block_hash(height: int, prev_hash: str, merkle: str) -> str:
    return crypto.sha256_hex(block_header_bytes(height, prev_hash, merkle))


@dataclass
class Block:
    height: int
    prev_hash: str
    merkle_root: str
    transactions: list[Transaction]
    block_hash: str
    status: str = STATUS_CONFIRMED

    @classmethod
    def create(
        cls,
        height: int,
        prev_hash: str,
        transactions: list[Transaction],
        status: str = STATUS_CONFIRMED,
    ) -> "Block":
        if status not in BLOCK_STATUSES:
            raise ValueError(f"unknown block status: {status}")
        ordered = sorted(transactions, key=lambda tx: tx.tx_id)
        merkle = crypto.merkle_root([tx.tx_id for tx in ordered])
        block_hash = compute_block_hash(height, prev_hash, merkle)
        return cls(
            height=height,
            prev_hash=prev_hash,
            merkle_root=merkle,
            transactions=ordered,
            block_hash=block_hash,
            status=status,
        )

    def to_dict(self) -> dict:
        return {
            "height": self.height,
            "prev_hash": self.prev_hash,
            "merkle_root": self.merkle_root,
            "block_hash": self.block_hash,
            "status": self.status,
            "transactions": [tx.to_dict() for tx in self.transactions],
        }

    @classmethod
    def from_dict(cls, data: dict) -> "Block":
        # State files written before the status machine existed have no
        # "status" key; every block in such a file was final, so they load
        # as confirmed. This compatibility default never extends to numeric
        # coercion: the raw height must already be a non-boolean,
        # non-negative integer — a string, float or bool is rejected, never
        # converted.
        status = data.get("status", STATUS_CONFIRMED)
        if status not in BLOCK_STATUSES:
            raise ValueError(f"unknown block status: {status}")
        height = data["height"]
        if isinstance(height, bool) or not isinstance(height, int) or height < 0:
            raise ValueError("block height must be a non-negative integer")
        transactions = data["transactions"]
        if not isinstance(transactions, list):
            raise ValueError("block transactions must be a list")
        return cls(
            height=height,
            prev_hash=data["prev_hash"],
            merkle_root=data["merkle_root"],
            block_hash=data["block_hash"],
            transactions=[Transaction.from_dict(t) for t in transactions],
            status=status,
        )

    def to_summary(self) -> dict:
        """Response shape for GET /v1/blocks/{height}."""
        return {
            "height": self.height,
            "block_hash": self.block_hash,
            "prev_hash": self.prev_hash,
            "merkle_root": self.merkle_root,
            "status": self.status,
            "transaction_ids": [tx.tx_id for tx in self.transactions],
        }

    Only ``0`` or a digit string whose first digit is non-zero is accepted:
    leading zeros, signs, whitespace and non-string types are all rejected.
    """
    if not isinstance(value, str) or not value:
        return None
    if value != "0" and (not value.isdigit() or value[0] == "0"):
        return None
    return int(value)


def _parse_ascii_decimal(value: object) -> int | None:
    """Like ``_parse_decimal`` but restricted to ASCII digits.

    ``str.isdigit`` also accepts non-ASCII digits (Arabic-Indic, superscripts
    and the like) that ``int`` then converts; the transaction-index range
    parameters reject those outright.
    """
    if not isinstance(value, str) or not value or not value.isascii():
        return None
    return _parse_decimal(value)


# Heights only ever index the canonical chain list, whose length never
# approaches this value; a well-formed height string with more digits folds
# to it instead of being converted to a giant integer. This keeps parsing
# independent of the interpreter's integer-string digit cap, so an
# over-long but well-formed request-body height stays a benign unknown
# height rather than raising.
_HEIGHT_BEYOND_CHAIN = 10**18
_HEIGHT_MAX_DIGITS = len(str(_HEIGHT_BEYOND_CHAIN)) - 1  # 18


def _parse_height_decimal(value: object) -> int | None:
    """Parse a height as a strict non-negative ASCII decimal string.

    Only the literal ``"0"`` or a string whose first character is an ASCII
    digit ``1``-``9`` and whose remaining characters are all ASCII digits
    ``0``-``9`` is accepted. The empty string, leading zeros, signs,
    surrounding or interior whitespace, decimal points, scientific notation
    and any non-ASCII digits (full-width, Arabic-Indic, superscript or mixed
    scripts — which ``str.isdigit``/``int`` would otherwise accept) are all
    rejected outright, with no normalization or truncation. Non-string
    values (numbers, booleans, null) are rejected as well.

    A well-formed string with more than
    ``_HEIGHT_MAX_DIGITS`` digits folds to ``_HEIGHT_BEYOND_CHAIN`` rather
    than undergoing an arbitrarily large (and possibly digit-capped)
    conversion: it can only name an unknown height.
    """
    if not isinstance(value, str) or not value:
        return None
    if not value.isascii() or not value.isdigit():
        return None
    if len(value) > 1 and value[0] == "0":
        return None
    if len(value) > _HEIGHT_MAX_DIGITS:
        return _HEIGHT_BEYOND_CHAIN
    return int(value)


class LedgerService:
    def __init__(
        self,
        store: LedgerStore,
        initial_balance: int = DEFAULT_INITIAL_BALANCE,
        history_config: tuple[str, str, str] | None = None,
        sync_state_path: str | None = None,
    ) -> None:
        self.store = store
        # Optional read-only light-client sync-state audit. When set, the
        # value is the header-checkpoint path whose header/.state/.txn trio
        # GET /v1/light-client/sync-state audits purely read-only.
        self.sync_state_path = sync_state_path
        self.sync_state_enabled = sync_state_path is not None
        # Optional token-gated checkpoint-history endpoints. When set, the
        # triple is ``(checkpoint_path, signer_log_path, bearer_token)`` and
        # the store already knows the two paths for startup re-verification.
        if history_config is not None:
            self.history_path, self.history_trust_path, self.history_token = (
                history_config
            )
            self.history_enabled = True
        else:
            self.history_path = None
            self.history_trust_path = None
            self.history_token = None
            self.history_enabled = False
        # The snapshot-recorded endowment is the only balance-replay / balance
        # reporting parameter: a recovered store already knows its endowment, so
        # restarting with a different --initial-balance must not change any
        # legality or reported balance. Only a brand-new store (no recorded
        # value) adopts the constructor argument.
        if store.initial_balance is None:
            store.initial_balance = initial_balance
            self.initial_balance = initial_balance
        else:
            self.initial_balance = store.initial_balance

    # -- uniform request idempotency ----------------------------------------

    def execute_idempotent(
        self,
        method: str,
        target: str,
        key: str,
        body: object,
        callback,
        sort_keys: bool = True,
    ) -> tuple[int, dict, bool, str | None]:
        """Run one state-changing request under uniform idempotency.

        The fingerprint is the SHA-256 over the HTTP method, the full request
        target and the canonicalized (key-sorted, compact) JSON body. With the
        store lock held for the whole request:

        * a known key with the same fingerprint replays the cached 2xx status
          and the exact cached JSON text without executing the callback,
          touching the ledger or appending audit events — ``replayed=True``;
        * a known key with a different fingerprint is a 409 conflict and does
          not execute the callback;
        * a first request executes the callback while every persistence call
          is deferred. A 4xx/5xx result restores the full in-memory snapshot,
          runs any registered external-file undos and occupies no key; a 2xx
          result installs the record (status plus the exact response text) and
          performs exactly one atomic write carrying the business change, its
          audit events and the record. A failing final write is reported 500
          (``persistence failed``), rolls everything back and occupies no key.

        Returns ``(status, body, replayed, cached_text)``: ``cached_text`` is
        the exact on-wire JSON text for a 2xx first/replay response (so first
        and replay bytes are identical), otherwise None.
        """
        canonical = canonical_request_body(body)
        if canonical is None:
            return (
                400,
                {"error": "request fingerprint could not be formed"},
                False,
                None,
            )
        fingerprint = request_fingerprint(method, target, canonical)
        with self.store.lock:
            record = self.store.idempotency.get(key)
            if record is not None:
                if record["fingerprint"] != fingerprint:
                    return (
                        409,
                        {"error": "idempotency key conflict"},
                        False,
                        None,
                    )
                return (
                    record["status"],
                    json.loads(record["body"]),
                    True,
                    record["body"],
                )

            snapshot = self.store.snapshot_mutable_state()
            self.store.begin_persistence()
            try:
                status, result = callback()
            except BaseException:
                # A business method raises only after its own save() failed
                # (its internal rollback already ran); perform the final
                # all-or-nothing restoration and answer persistence failed.
                self.store.abort_persistence()
                self.store.restore_mutable_state(snapshot)
                return 500, {"error": "persistence failed"}, False, None
            if not isinstance(status, int) or not (200 <= status < 300):
                # A 4xx/5xx business answer occupies no key: discard every
                # incidental mutation (e.g. an expired-sync sweep), run the
                # deferred external-file undos and leave the prior state.
                self.store.abort_persistence()
                self.store.restore_mutable_state(snapshot)
                return status, result, False, None
            text = json.dumps(
                result, ensure_ascii=False, sort_keys=sort_keys
            )
            entry = {
                "key": key,
                "method": method,
                "target": target,
                "request": canonical,
                "fingerprint": fingerprint,
                "status": status,
                "body": text,
            }
            try:
                self.store.commit_persistence(entry)
            except BaseException:
                self.store.abort_persistence()
                self.store.restore_mutable_state(snapshot)
                return 500, {"error": "persistence failed"}, False, None
            return status, result, False, text

    # -- transactions -------------------------------------------------------

    def submit_transaction(self, payload: object) -> tuple[int, dict]:
        """Validate and enqueue a transaction. Returns (status, body)."""
        if not isinstance(payload, dict):
            return 400, {"error": "request body must be a JSON object"}
        for field in REQUIRED_TX_FIELDS:
            if field not in payload:
                return 400, {"error": f"missing field: {field}"}

        sender = payload["from"]
        recipient = payload["to"]
        amount = payload["amount"]
        signature = payload["signature"]

        if not isinstance(sender, str) or not sender:
            return 400, {"error": "field 'from' must be a non-empty string"}
        if not isinstance(recipient, str) or not recipient:
            return 400, {"error": "field 'to' must be a non-empty string"}
        # bool is a subclass of int: reject it and all non-int types explicitly.
        if not isinstance(amount, int) or isinstance(amount, bool) or amount <= 0:
            return 400, {"error": "field 'amount' must be a positive integer"}
        if not isinstance(signature, str) or not signature:
            return 400, {"error": "field 'signature' must be a non-empty string"}

        message = crypto.canonical_message(sender, recipient, amount)
        if not crypto.verify_signature(sender, message, signature):
            return 400, {"error": "invalid signature"}

        tx = Transaction(sender, recipient, amount, signature)
        with self.store.lock:
            if tx.tx_id in self.store.pending:
                return 409, {"error": "transaction already pending", "tx_id": tx.tx_id}
            if any(tx.tx_id == existing.tx_id for block in self.store.chain for existing in block.transactions):
                return 409, {"error": "transaction already confirmed", "tx_id": tx.tx_id}
            if self.available_balance(sender) < amount:
                return 400, {"error": "insufficient balance"}
            self.store.pending[tx.tx_id] = tx
            # First successful enqueue: one transaction_submitted event,
            # persisted in the same atomic write as the mempool change.
            self.store.append_audit_event(
                EVENT_TRANSACTION_SUBMITTED,
                {
                    "tx_id": tx.tx_id,
                    "from": tx.sender,
                    "to": tx.recipient,
                    "amount": tx.amount,
                },
            )
            try:
                self.store.save()
            except BaseException:
                # Persistence failed: drop the in-memory enqueue and its
                # event so memory keeps matching the last durably committed
                # state.
                self.store.pending.pop(tx.tx_id, None)
                self.store.truncate_audit_events(1)
                raise
        return 202, {"tx_id": tx.tx_id}

    # -- sequenced (retryable, nonce-ordered) transactions ------------------

    def submit_sequenced_transaction(
        self, payload: object
    ) -> tuple[int, dict]:
        """POST /v1/transactions/sequenced — validate and reserve a sequenced
        transfer. Returns ``(status, body)``.

        The payload is exactly ``{from, to, amount, nonce, signature}``:
        ``from``/``to`` non-empty strings, ``amount`` a positive non-boolean
        integer, ``nonce`` a non-negative non-boolean integer and ``signature``
        a non-empty string; the signed message is
        ``ledger-sequenced-transfer-v1\\n{"amount":A,"from":F,"nonce":N,"to":T}``
        and the signing key must derive ``from``. Every field, type,
        signature or balance defect is ``400 {"error": "input"}``.

        Sequencing: ``nonce`` must equal the account's current
        ``next_sequence`` (the dense prefix of confirmed nonces plus the
        contiguous pending-tip/mempool reservations). A smaller nonce that
        names a different transaction, or any nonce past the next one (a
        gap), is ``409 {"error": "sequence_conflict", "next_sequence": N}``.
        A retried identical request (same from/to/amount/nonce/signature,
        hence same tx_id) is idempotent: it replays the first result with
        status 200 and no new state or audit event, whether the transfer is
        still queued, packed into the pending tip or already confirmed.
        """
        if not isinstance(payload, dict):
            return 400, {"error": "input"}
        for field in REQUIRED_SEQUENCED_TX_FIELDS:
            if field not in payload:
                return 400, {"error": "input"}

        sender = payload["from"]
        recipient = payload["to"]
        amount = payload["amount"]
        nonce = payload["nonce"]
        signature = payload["signature"]

        if not isinstance(sender, str) or not sender:
            return 400, {"error": "input"}
        if not isinstance(recipient, str) or not recipient:
            return 400, {"error": "input"}
        # bool is a subclass of int: reject it and all non-int types explicitly.
        if isinstance(amount, bool) or not isinstance(amount, int) or amount <= 0:
            return 400, {"error": "input"}
        # bool is likewise rejected for nonce; negatives and non-ints too.
        if isinstance(nonce, bool) or not isinstance(nonce, int) or nonce < 0:
            return 400, {"error": "input"}
        if not isinstance(signature, str) or not signature:
            return 400, {"error": "input"}

        message = crypto.sequenced_message(sender, recipient, amount, nonce)
        if not crypto.verify_signature(sender, message, signature):
            return 400, {"error": "input"}

        tx = Transaction(sender, recipient, amount, signature, nonce)
        with self.store.lock:
            # Idempotent retries are decided before any sequence or balance
            # gate: the same signed request (same tx_id) always returns the
            # original result, whether it is queued, packed unconfirmed or
            # confirmed, and never appends a second transaction_submitted
            # event.
            existing_status = self._sequenced_tx_location(tx.tx_id)
            if existing_status is not None:
                return 200, {"tx_id": tx.tx_id, "nonce": nonce}

            # A different transaction already occupying this (sender, nonce)
            # slot, or a nonce past the next acceptable value, is a sequence
            # conflict naming the current next_sequence.
            state = self.store.sequences.get(sender)
            next_sequence = self.store.sequence_next(state)
            if nonce != next_sequence:
                return 409, {
                    "error": "sequence_conflict",
                    "next_sequence": next_sequence,
                }
            # Balance is checked exactly like a legacy submission against
            # the available (confirmed minus pending-tip and mempool spends)
            # balance; sequenced reservations spend like any mempool entry.
            if self.available_balance(sender) < amount:
                return 400, {"error": "input"}
            self.store.pending[tx.tx_id] = tx
            # First successful reservation: one transaction_submitted event
            # (carrying nonce), persisted in the same atomic write as the
            # mempool change.
            self.store.append_audit_event(
                EVENT_TRANSACTION_SUBMITTED,
                {
                    "tx_id": tx.tx_id,
                    "from": tx.sender,
                    "to": tx.recipient,
                    "amount": tx.amount,
                    "nonce": tx.nonce,
                },
            )
            try:
                self.store.save()
            except BaseException:
                # Persistence failed: drop the in-memory reservation and its
                # event so memory keeps matching the last committed state.
                self.store.pending.pop(tx.tx_id, None)
                self.store.truncate_audit_events(1)
                raise
        return 202, {"tx_id": tx.tx_id, "nonce": nonce}

    def _validate_sequenced_batch(
        self, payload: object
    ) -> tuple[int, dict | None, list[Transaction] | None]:
        """Validate a sequenced-batch request body.

        Returns ``(None, None, transactions)`` when the shape, types and
        signatures are all sound, otherwise ``(status, body, None)``. The
        envelope is exactly ``{"transactions": [item, ...]}`` with a
        non-empty list; each item carries exactly the five single-entry
        fields with the single-entry types. Field/type and signature defects
        are ``400 {"error": "input", "index": I}`` at the first offending
        item; envelope defects are ``400 {"error": "input"}``.
        """
        if not isinstance(payload, dict) or set(payload) != {"transactions"}:
            return 400, {"error": "input"}, None
        items = payload["transactions"]
        if not isinstance(items, list) or not items:
            return 400, {"error": "input"}, None
        transactions: list[Transaction] = []
        for index, item in enumerate(items):
            if not isinstance(item, dict) or set(item) != set(
                REQUIRED_SEQUENCED_TX_FIELDS
            ):
                return 400, {"error": "input", "index": index}, None
            sender = item["from"]
            recipient = item["to"]
            amount = item["amount"]
            nonce = item["nonce"]
            signature = item["signature"]
            if not isinstance(sender, str) or not sender:
                return 400, {"error": "input", "index": index}, None
            if not isinstance(recipient, str) or not recipient:
                return 400, {"error": "input", "index": index}, None
            if (
                isinstance(amount, bool)
                or not isinstance(amount, int)
                or amount <= 0
            ):
                return 400, {"error": "input", "index": index}, None
            if (
                isinstance(nonce, bool)
                or not isinstance(nonce, int)
                or nonce < 0
            ):
                return 400, {"error": "input", "index": index}, None
            if not isinstance(signature, str) or not signature:
                return 400, {"error": "input", "index": index}, None
            message = crypto.sequenced_message(sender, recipient, amount, nonce)
            if not crypto.verify_signature(sender, message, signature):
                return 400, {"error": "input", "index": index}, None
            transactions.append(
                Transaction(sender, recipient, amount, signature, nonce)
            )
        return None, None, transactions

